<?php $fields=['max_customers'=>'Total customers','max_team_members'=>'Team members','max_domains'=>'Domains','max_contacts'=>'Contacts','daily_email_limit'=>'Emails per day','monthly_email_limit'=>'Emails per month','max_smtp_accounts'=>'SMTP accounts','max_api_keys'=>'API keys']; ?>
<section class="mt-7"><h2 class="text-xl font-extrabold">Customer and reseller packages</h2><p class="text-sm text-[#78908c]">A selected Unlimited option removes that quota ceiling.</p></section>
<section class="mt-6 grid gap-4 lg:grid-cols-2"><?php foreach(['customer'=>'User packages','reseller'=>'Reseller packages'] as$type=>$heading): ?><div class="card p-5"><h3 class="font-extrabold"><?= $heading ?></h3><div class="mt-4 space-y-3"><?php foreach($plans as$p): if($p['audience_type']!==$type)continue; ?><details class="rounded-2xl bg-[#e7f2ef] p-4"><summary class="cursor-pointer"><span class="flex justify-between gap-3"><b><?= esc($p['name']) ?></b><span><?= esc($p['currency']) ?> <?= number_format($p['price'],2) ?>/<?= esc($p['billing_cycle']) ?> · <?= $p['is_active']?'Active':'Inactive' ?></span></span></summary><form action="<?= base_url('admin/plans/'.$p['uuid']) ?>" method="post" class="mt-4 space-y-3"><?= csrf_field() ?><div class="grid grid-cols-2 gap-2"><input name="name" value="<?= esc($p['name']) ?>" class="field" required><input name="price" type="number" min="0" step="0.01" value="<?= esc($p['price']) ?>" class="field"></div><div class="grid gap-2 sm:grid-cols-2"><?php foreach($fields as$f=>$label): ?><label class="text-xs font-bold"><?= $label ?><input name="<?= $f ?>" type="number" min="0" value="<?= $p[$f]===null?'0':esc($p[$f]) ?>" class="field mt-1"><span class="mt-1 flex gap-2 font-normal"><input type="checkbox" name="unlimited[]" value="<?= $f ?>" <?= $p[$f]===null?'checked':'' ?>> Unlimited</span></label><?php endforeach ?></div><label class="flex gap-2 text-sm"><input type="checkbox" name="is_active" value="1" <?= $p['is_active']?'checked':'' ?>> Available for assignment</label><button class="btn shadow-soft">Update package</button></form></details><?php endforeach ?></div></div><?php endforeach ?></section>
<section class="card mt-6 p-6"><h3 class="font-extrabold">Create package</h3><form action="<?= base_url('admin/plans') ?>" method="post" class="mt-5 space-y-4"><?= csrf_field() ?><div class="grid gap-3 md:grid-cols-5"><input name="name" class="field" required placeholder="Package name"><select name="audience_type" class="field"><option value="customer">Customer/user</option><option value="reseller">Reseller</option></select><input name="price" type="number" min="0" step="0.01" value="0" class="field" required><input name="currency" value="USD" maxlength="3" class="field" required><select name="billing_cycle" class="field"><option value="monthly">Monthly</option><option value="yearly">Yearly</option><option value="one_time">One time</option></select></div><div class="grid gap-3 md:grid-cols-2 xl:grid-cols-4"><?php foreach($fields as$f=>$label): ?><label class="rounded-2xl bg-[#e7f2ef] p-3"><span class="text-xs font-bold"><?= $label ?></span><input name="<?= $f ?>" type="number" min="0" value="0" class="field mt-2"><span class="mt-2 flex gap-2 text-xs"><input type="checkbox" name="unlimited[]" value="<?= $f ?>"> Unlimited</span></label><?php endforeach ?></div><button class="btn btn-primary">Create package</button></form></section>
